        return ADCS_E_DEGENERATE;
    }

    // 4. Collinearity check
    // Cosine of angle between primary and secondary vectors
    dot_pb_sb = adcs_vec3_dot(pb, sb) / (norm_pb * norm_sb);
    dot_pi_si = adcs_vec3_dot(pi, si) / (norm_pi * norm_si);

    // If absolute cosine is close to 1, vectors are collinear
    if (fabs(dot_pb_sb) > (1.0 - ADCS_EPS_COLLINEAR) || 
        fabs(dot_pi_si) > (1.0 - ADCS_EPS_COLLINEAR)) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    // 5. Construct Body Basis Matrix B
    // Column 1: Normalized Primary Body Vector
    b1 = adcs_vec3_scale(pb, 1.0 / norm_pb);

    // Column 2: Normalized Cross Product of Primary and Secondary Body Vectors
    b2 = adcs_vec3_cross(&b1, sb);
    norm_b2 = adcs_vec3_norm(&b2);
    if (norm_b2 < ADCS_EPS_NORM) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    b2 = adcs_vec3_scale(&b2, 1.0 / norm_b2);

    // Column 3: Cross Product of Col 1 and Col 2 (to ensure orthogonality)
    b3 = adcs_vec3_cross(&b1, &b2);

    // Fill B matrix (columns are basis vectors)
    B.m[0][0] = b1.x; B.m[1][0] = b1.y; B.m[2][0] = b1.z;
    B.m[0][1] = b2.x; B.m[1][1] = b2.y; B.m[2][1] = b2.z;
    B.m[0][2] = b3.x; B.m[1][2] = b3.y; B.m[2][2] = b3.z;

    // 6. Construct Inertial Basis Matrix I
    // Column 1: Normalized Primary Inertial Vector
    i1 = adcs_vec3_scale(pi, 1.0 / norm_pi);

    // Column 2: Normalized Cross Product of Primary and Secondary Inertial Vectors
    i2 = adcs_vec3_cross(&i1, si);
    norm_i2 = adcs_vec3_norm(&i2);
    if (norm_i2 < ADCS_EPS_NORM) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    i2 = adcs_vec3_scale(&i2, 1.0 / norm_i2);

    // Column 3: Cross Product of Col 1 and Col 2
    i3 = adcs_vec3_cross(&i1, &i2);

    // Fill I matrix
    I.m[0][0] = i1.x; I.m[1][0] = i1.y; I.m[2][0] = i1.z;
    I.m[0][1] = i2.x; I.m[1][1] = i2.y; I.m[2][1] = i2.z;
    I.m[0][2] = i3.x; I.m[1][2] = i3.y; I.m[2][2] = i3.z;

    // 7. Compute Rotation Matrix C_bi = B * I^T
    Rt = adcs_mat3_transpose(&I);
    C = adcs_mat3_mul(&B, &Rt);

    // 8. Ensure Determinant is +1 (Proper Rotation)
    // If det is negative, it's a reflection, flip one axis of B
    if (adcs_mat3_det(&C) < 0.0) {
        B.m[0][0] = -B.m[0][0];
        B.m[1][0] = -B.m[1][0];
        B.m[2][0] = -B.m[2][0];
        C = adcs_mat3_mul(&B, &Rt);
    }

    *out = C;
    return ADCS_OK;
}

